#!/usr/bin/env python3
"""Rerunnable source-closure extension over the audited selector pair; no Lean."""
import hashlib,json,os,subprocess,sys
from pathlib import Path
if not __debug__ or os.environ.get('PYTHONOPTIMIZE') or not sys.flags.isolated or not sys.flags.no_site:raise RuntimeError('requires nonoptimized python3 -I -S')
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[4];RESEARCH=ROOT/'Computability/DiophantineConsistency/research/ordinary12-ipra-bridge';REVIEW=ROOT/'Computability/DiophantineConsistency/reviews/compact44-selector-graph-independent-audit';PROVISIONAL=RESEARCH/'compact44-selector-period-closure-plan';PARENT_REPLAY=RESEARCH/'compact44-selector-graph-pair-prototype/replay.py';PARENT_SCAN=RESEARCH/'compact44-selector-graph-closure-plan/scan.json';GRANDPARENT=ROOT/'Computability/DiophantineConsistency/reviews/compact44-same-witness-saturation-independent-audit/CHECK.json'
PINS={REVIEW/'audit.py':'3a3b6b5640daae129a12e01ef13d77a9c1e40340a34bcc19dada0797be3cb018',REVIEW/'CHECK.json':'514d5b0141dcaf24a6daaa8f43c86fd94bfa063d68ec960eee491de887a098db',REVIEW/'terminal-observation.json':'7aee61ee1158d68e8d9db84f33cd2030b16515ee0919175b464f35c993340c02',PROVISIONAL/'scan.py':'f692a7f5e4c1dc9c00dcb87c554b8aafbb5333ba11c7b2a078760bc6714d7bab',PROVISIONAL/'scan.json':'752f8e4ebfd71f25b54814e72fa4c6b129544bc02c0b50ede3afde6f93316f9d',PARENT_REPLAY:'f6a4b8321fa2c532d55c6816d5fbd7c9ebe981604949c1695340f965f3525117',PARENT_SCAN:'514042651521a9200019e4fed4fa296ca7008c57eb8f3c3a16d8d92f97d1a035',GRANDPARENT:'5d8c620fc76d741a7d1b398f9e442ce7dfea83a90cd39a42c53e9320d75dd754'}
H=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
for p,h in PINS.items():assert p.is_file() and H(p)==h,('input drift',str(p))
scan=json.loads((PROVISIONAL/'scan.json').read_bytes());assert scan['status']=='PROVISIONAL_SELECTOR_PERIOD_SOURCE_CLOSURE_NOT_A_BUILD' and scan['parent_independent_audit']=='PENDING' and len(scan['objects'])==150 and len(scan['direct_slots'])==20 and len(scan['target_slots'])==20 and len(scan['init_slots'])==10
obs=json.loads((REVIEW/'terminal-observation.json').read_bytes());audit=json.loads((REVIEW/'CHECK.json').read_bytes());assert audit['status']=='PASS_INDEPENDENT_SELECTOR_GRAPH_PAIR_ARTIFACT_AUDIT' and audit['receipt_sha256']==scan['parent_receipt_sha256'] and type(obs['observed_exit']) is int and obs['observed_exit']==0 and obs['lean_launched'] is False and obs['check_sha256']==PINS[REVIEW/'CHECK.json']
q=subprocess.run([sys.executable,'-I','-S','-B',str(PROVISIONAL/'scan.py')],cwd=ROOT,capture_output=True,timeout=180);assert q.returncode==0 and not q.stderr and q.stdout==(PROVISIONAL/'scan.json').read_bytes(),('provisional scan',q.returncode,q.stderr)
q=subprocess.run([sys.executable,'-I','-S','-B',str(REVIEW/'audit.py')],cwd=ROOT,capture_output=True,timeout=1800);assert q.returncode==0 and not q.stderr and json.loads(q.stdout)==audit,('selector artifact audit',q.returncode,q.stderr)
code="import json,runpy,sys; d=runpy.run_path(sys.argv[1]); s,p=d['verify'](); print(json.dumps({'scan':s,'parent':p},sort_keys=True))"
q=subprocess.run([sys.executable,'-I','-S','-B','-c',code,str(PARENT_REPLAY)],cwd=ROOT,capture_output=True,timeout=3000);assert q.returncode==0 and not q.stderr and json.loads(q.stdout)=={'scan':json.loads(PARENT_SCAN.read_bytes()),'parent':json.loads(GRANDPARENT.read_bytes())},('selector full parent verify',q.returncode,q.stderr)
for p,h in PINS.items():assert p.is_file() and H(p)==h,('input drift after audits',str(p))
print(json.dumps({'status':'SELECTOR_PERIOD_AUTHENTICATED_SOURCE_CLOSURE_NOT_A_BUILD','provisional_scan_sha256':PINS[PROVISIONAL/'scan.json'],'parent_audit_sha256':PINS[REVIEW/'CHECK.json'],'parent_receipt_sha256':scan['parent_receipt_sha256'],'source_sha256':scan['source_sha256'],'objects_per_side':150,'direct_slots':20,'target_slots':20,'init_slots':10,'scope':'Read-only current parent artifact and complete nested parent verification plus point-in-time provisional inventory; no Lean paired build, retained tuple binding, graph-column decoder or iPRA proof.'},indent=2))
